#!/usr/bin/env python3
"""Patch 99: admin copies are saved by source name and visible to admins only, with a diff in the final check. Needs patch 98. Careerflow platform enhancements. Run from the repo root (the folder that holds backend/ and frontend/).
Safe to run twice: files already applied are skipped."""
import os, sys, zlib, base64
sys.stdout.reconfigure(errors='replace')
NEW = {'backend/migrations/versions/035_admin_copies.py': '', 'backend/app/services/admin_upload.py': '', 'backend/app/api/v1/routes/admin_upload.py': '', 'frontend/src/api/adminUpload.ts': '', 'frontend/src/components/enh/AdminUpload.tsx': '', 'frontend/src/components/enh/AdminBatchUpload.tsx': ''}
MOD = {'backend/app/models/all_models.py': [('class SourceObservation(Base):\n    """What an extractor or reviewer saw while working a source: a page that would not open, a login wall, no data.\n    A person\'s check is done once they have at least one row (\'none\' means they looked and found no issue)."""\n    __tablename__ = "source_observations"\n\n    id = Column(String(36), primary_key=True, default=new_uuid)\n    source_id = Column(String(36), ForeignKey("sources.id", ondelete="CASCADE"), nullable=False, index=True)\n    user_id = Column(String(36), ForeignKey("users.id", ondelete="SET NULL"), nullable=True, index=True)\n    role = Column(String(12), nullable=False, default="extractor")      # extractor | reviewer | admin\n    kind = Column(String(24), nullable=False)                           # see services/observations.KINDS, or \'none\'\n    note = Column(Text, nullable=True)\n    record_id = Column(String(36), ForeignKey("extracted_records.id", ondelete="SET NULL"), nullable=True)\n    created_at = Column(DateTime(timezone=True), default=now_utc, index=True)\n', 'class SourceObservation(Base):\n    """What an extractor or reviewer saw while working a source: a page that would not open, a login wall, no data.\n    A person\'s check is done once they have at least one row (\'none\' means they looked and found no issue)."""\n    __tablename__ = "source_observations"\n\n    id = Column(String(36), primary_key=True, default=new_uuid)\n    source_id = Column(String(36), ForeignKey("sources.id", ondelete="CASCADE"), nullable=False, index=True)\n    user_id = Column(String(36), ForeignKey("users.id", ondelete="SET NULL"), nullable=True, index=True)\n    role = Column(String(12), nullable=False, default="extractor")      # extractor | reviewer | admin\n    kind = Column(String(24), nullable=False)                           # see services/observations.KINDS, or \'none\'\n    note = Column(Text, nullable=True)\n    record_id = Column(String(36), ForeignKey("extracted_records.id", ondelete="SET NULL"), nullable=True)\n    created_at = Column(DateTime(timezone=True), default=now_utc, index=True)\n\n\nclass AdminCopy(Base):\n    """Data an admin saved for their own checking and final review. It is kept apart from the source, so extractors and reviewers never see it,\n    and it is kept by the source\'s name, so it is still there when the source is deleted and pulled again."""\n    __tablename__ = "admin_copies"\n\n    id = Column(String(36), primary_key=True, default=new_uuid)\n    source_id = Column(String(36), ForeignKey("sources.id", ondelete="SET NULL"), nullable=True, index=True)\n    name_key = Column(String(300), nullable=False, index=True)\n    source_name = Column(String(512), nullable=False)\n    project_id = Column(String(36), nullable=True, index=True)\n    batch_id = Column(String(36), nullable=False, index=True)\n    batch_label = Column(String(200), nullable=True)\n    file = Column(String(300), nullable=True)\n    records = Column(JSON, nullable=False, default=list)      # [{"name", "fields"}]\n    record_count = Column(Integer, default=0)\n    valid_count = Column(Integer, default=0)\n    created_by = Column(String(36), ForeignKey("users.id", ondelete="SET NULL"), nullable=True)\n    created_at = Column(DateTime(timezone=True), default=now_utc, index=True)\n    applied_at = Column(DateTime(timezone=True), nullable=True)\n')], 'backend/app/api/v1/routes/versions.py': [('def _round(db: Session, source, round_id: str) -> SourceRound:\n    rd = db.query(SourceRound).filter(SourceRound.id == round_id, SourceRound.source_id == source.id).first()\n    if not rd:', 'def _round(db: Session, source, round_id: str, user=None) -> SourceRound:\n    rd = db.query(SourceRound).filter(SourceRound.id == round_id, SourceRound.source_id == source.id).first()\n    if rd and (rd.reason or "").startswith("Reference") and not (user and rl.is_admin(user)):\n        rd = None            # an admin\'s reference copy is for admins only\n    if not rd:'), ('return ver.compare(db, source, _round(db, source, round_id))', 'return ver.compare(db, source, _round(db, source, round_id, user))'), ('rd = _round(db, source, round_id)\n    body = json.dumps', 'rd = _round(db, source, round_id, user)\n    body = json.dumps'), ('rd = _round(db, source, round_id)\n    rows = [dict', 'rd = _round(db, source, round_id, user)\n    rows = [dict'), ('"versions": ver.listing(db, source),', '"versions": [v for v in ver.listing(db, source) if admin or v["kind"] != "reference"],')], 'frontend/src/pages/SourceDetail.tsx': [("import { AdminModePicker, AdminDraftBanner, type UploadMode } from '@/components/enh/AdminUpload'", "import { AdminModePicker, AdminDraftBanner, AdminCopiesPanel, AdminRecordCopy, type UploadMode } from '@/components/enh/AdminUpload'"), ("useState<UploadMode>('draft')", "useState<UploadMode>('reference')"), ("'Saved as a draft. It is not with the reviewers yet. '", "'Loaded as data, not submitted. '"), ("'Kept as a reference copy under Versions. The source data is unchanged. '", "'Saved privately. Only admins can see it, and the source is unchanged. '"), ('{sourceId && <VersionsPanel sourceId={sourceId} onRestored={() => { load(); setRawFilesLoaded(false) }} />}', '{sourceId && <VersionsPanel sourceId={sourceId} onRestored={() => { load(); setRawFilesLoaded(false) }} />}\n        {isAdmin && sourceId && <AdminCopiesPanel sourceId={sourceId} onApplied={() => { load(); setRawFilesLoaded(false) }} />}'), ("                {isAdmin && timeline.current_status === 'pending_admin_review' && (\n", "                {isAdmin && sourceId && showTimeline && <AdminRecordCopy sourceId={sourceId} recordId={showTimeline} />}\n                {isAdmin && timeline.current_status === 'pending_admin_review' && (\n")]}
root = os.getcwd()
if not (os.path.isdir(os.path.join(root, 'backend')) and os.path.isdir(os.path.join(root, 'frontend'))):
    sys.exit('Run this from the repo root (the folder containing backend and frontend).')
def rd(p): return open(p, encoding='utf-8', newline='').read()
done = skipped = 0; bad = []
for rel, hunks in MOD.items():
    p = os.path.join(root, rel)
    if not os.path.exists(p): bad.append(rel + ' (missing)'); continue
    raw = rd(p); crlf = '\r\n' in raw; t = raw.replace('\r\n', '\n'); changed = False
    for old, new in hunks:
        if new in t and not (new in old and new != old): continue
        elif t.count(old) == 1: t = t.replace(old, new); changed = True
        elif new in t: continue
        else: bad.append(rel + ' (a section does not match; file differs from expected version)'); break
    else:
        if changed:
            open(p, 'w', encoding='utf-8', newline='').write(t.replace('\n', '\r\n') if crlf else t); done += 1; print('updated ', rel)
        else: skipped += 1
for rel, blob in NEW.items():
    p = os.path.join(root, rel); data = zlib.decompress(base64.b64decode(blob))
    if os.path.exists(p) and open(p, 'rb').read() == data: skipped += 1; continue
    os.makedirs(os.path.dirname(p), exist_ok=True); open(p, 'wb').write(data); done += 1; print('wrote   ', rel)
print(f'\n{done} changed, {skipped} already applied.')
if bad:
    print('\nPROBLEMS:'); [print(' -', b) for b in bad]; sys.exit(1)
